// 发票下载接口：登录用户按发票 id 下载 PDF 发票文件
const express = require('express');
const router = express.Router();
const db = require('../db'); // 已初始化的 PostgreSQL 连接池（pg）

// 前置全局中间件 verifyToken 已完成 JWT 校验，
// 到达本路由时 req.user = { id, username } 必然存在
router.get('/invoices/:invoiceId/download', async (req, res) => {
  try {
    const invoiceId = req.params.invoiceId; // 外部输入：URL 路径参数，请求者可控
    // 按发票主键查询文件记录
    const result = await db.query(
      'SELECT file_path, file_name FROM invoices WHERE id = $1',
      [invoiceId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: '发票不存在' });
    }
    const { file_path, file_name } = result.rows[0];
    // 将查到的文件回传给请求者
    res.download(file_path, file_name);
  } catch (err) {
    res.status(500).json({ error: '服务器内部错误' });
  }
});

module.exports = router;
```

