from flask import Flask, request, session, redirect, url_for
from werkzeug.security import check_password_hash
import sqlite3
import os

app = Flask(__name__)
app.secret_key = os.environ["SESSION_SECRET"]  # 签名密钥由环境注入，避免硬编码凭据

# 预登录阶段：匿名访客也会持有会话（记录语言偏好），会话在登录前已经存在
@app.route("/pref", methods=["POST"])
def set_pref():
    session["lang"] = request.form.get("lang", "zh")
    return "ok"

@app.route("/login", methods=["POST"])
def login():
    # 外部输入入口：登录表单提交的用户名与密码
    username = request.form.get("username", "")
    password = request.form.get("password", "")
    conn = sqlite3.connect("app.db")
    row = conn.execute(
        "SELECT id, password_hash FROM users WHERE username = ?", (username,)
    ).fetchone()
    conn.close()
    if row and check_password_hash(row[1], password):
        # 密码校验通过后直接在旧会话上写入登录态，未调用 session.clear() 重建会话
        session["user_id"] = row[0]
        return redirect(url_for("dashboard"))
    return "用户名或密码错误", 401

@app.route("/dashboard")
def dashboard():
    if "user_id" not in session:
        return redirect(url_for("login"))
    return f"欢迎用户 {session['user_id']}"
```

