const express = require('express');
const session = require('express-session');
const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(session({
  secret: 'demo-only-secret', // 演示占位，非生产凭据
  cookie: { httpOnly: true, sameSite: 'lax' } // 仅靠 SameSite 同源假设防跨站
}));

// 模拟账户余额表；登录路由（略）会把用户名写入 req.session.user
const accounts = { alice: { balance: 1000 }, bob: { balance: 500 } };

app.post('/transfer', (req, res) => {
  if (!req.session.user) { // 只验证「已登录」，不验证请求来源
    return res.status(401).send('login required');
  }
  const from = req.session.user;
  const to = req.body.to; // 外部输入：收款账户
  const amount = parseInt(req.body.amount, 10); // 外部输入：转账金额
  if (!accounts[from] || !accounts[to] || !(amount > 0)) {
    return res.status(400).send('bad params');
  }
  // 直接落账：无 CSRF token 校验，也无密码/验证码等二次确认
  accounts[from].balance -= amount;
  accounts[to].balance += amount;
  res.send('transferred ' + amount + ' to ' + to);
});

app.listen(3000);
```
